export interface Config {
  port: number;
  debug: boolean;
  name: string;
}

export type ParseConfigResult =
  | { ok: true; config: Config }
  | { ok: false; errors: string[] };

const PORT_PATTERN = /^-?\d+$/;

export function parseConfig(
  env: Record<string, string | undefined>,
): ParseConfigResult {
  const errors: string[] = [];

  const rawPort = env.PORT;
  let port = 0;
  if (rawPort === undefined || rawPort.trim() === '') {
    errors.push('PORT is required');
  } else if (!PORT_PATTERN.test(rawPort.trim())) {
    errors.push(`PORT must be an integer, got "${rawPort}"`);
  } else {
    const parsed = Number.parseInt(rawPort.trim(), 10);
    if (parsed < 1 || parsed > 65535) {
      errors.push(`PORT must be between 1 and 65535, got "${rawPort}"`);
    } else {
      port = parsed;
    }
  }

  const rawDebug = env.DEBUG;
  let debug = false;
  if (rawDebug !== undefined && rawDebug !== '') {
    if (rawDebug === 'true') {
      debug = true;
    } else if (rawDebug === 'false') {
      debug = false;
    } else {
      errors.push(`DEBUG must be "true" or "false", got "${rawDebug}"`);
    }
  }

  const rawName = env.NAME;
  let name = 'dorbs';
  if (rawName !== undefined) {
    name = rawName;
  }

  if (errors.length > 0) {
    return { ok: false, errors };
  }

  return { ok: true, config: { port, debug, name } };
}

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { parseConfig } from './config.ts';

describe('parseConfig', () => {
  it('parses a valid environment with defaults', () => {
    const result = parseConfig({ PORT: '8080' });
    assert.deepEqual(result, {
      ok: true,
      config: { port: 8080, debug: false, name: 'dorbs' },
    });
  });

  it('parses debug true and a custom name', () => {
    const result = parseConfig({ PORT: '1', DEBUG: 'true', NAME: 'app' });
    assert.deepEqual(result, {
      ok: true,
      config: { port: 1, debug: true, name: 'app' },
    });
  });

  it('parses debug false and the upper port bound', () => {
    const result = parseConfig({ PORT: '65535', DEBUG: 'false' });
    assert.deepEqual(result, {
      ok: true,
      config: { port: 65535, debug: false, name: 'dorbs' },
    });
  });

  it('allows an empty NAME', () => {
    const result = parseConfig({ PORT: '3000', NAME: '' });
    assert.deepEqual(result, {
      ok: true,
      config: { port: 3000, debug: false, name: '' },
    });
  });

  it('reports a missing PORT', () => {
    const result = parseConfig({});
    assert.equal(result.ok, false);
    assert.deepEqual(result, { ok: false, errors: ['PORT is required'] });
  });

  it('reports an undefined PORT value', () => {
    const result = parseConfig({ PORT: undefined });
    assert.equal(result.ok, false);
    assert.deepEqual(result, { ok: false, errors: ['PORT is required'] });
  });

  it('reports a non-integer PORT', () => {
    const result = parseConfig({ PORT: 'abc' });
    assert.equal(result.ok, false);
    assert.deepEqual(result, {
      ok: false,
      errors: ['PORT must be an integer, got "abc"'],
    });
  });

  it('reports a fractional PORT', () => {
    const result = parseConfig({ PORT: '80.5' });
    assert.equal(result.ok, false);
    assert.deepEqual(result, {
      ok: false,
      errors: ['PORT must be an integer, got "80.5"'],
    });
  });

  it('reports an out-of-range PORT below 1', () => {
    const result = parseConfig({ PORT: '0' });
    assert.equal(result.ok, false);
    assert.deepEqual(result, {
      ok: false,
      errors: ['PORT must be between 1 and 65535, got "0"'],
    });
  });

  it('reports an out-of-range PORT above 65535', () => {
    const result = parseConfig({ PORT: '70000' });
    assert.equal(result.ok, false);
    assert.deepEqual(result, {
      ok: false,
      errors: ['PORT must be between 1 and 65535, got "70000"'],
    });
  });

  it('reports an invalid DEBUG', () => {
    const result = parseConfig({ PORT: '8080', DEBUG: 'yes' });
    assert.equal(result.ok, false);
    assert.deepEqual(result, {
      ok: false,
      errors: ['DEBUG must be "true" or "false", got "yes"'],
    });
  });

  it('collects every error instead of stopping at the first', () => {
    const result = parseConfig({ PORT: 'nope', DEBUG: 'maybe' });
    assert.equal(result.ok, false);
    assert.deepEqual(result, {
      ok: false,
      errors: [
        'PORT must be an integer, got "nope"',
        'DEBUG must be "true" or "false", got "maybe"',
      ],
    });
  });
});

